function msg(type,text){setFeedback(status,type,text)}
function fill(sel,rows,valueKey='id'){let current=sel.value;sel.textContent='';rows.forEach(r=>{let o=document.createElement('option');o.value=r[valueKey];o.textContent=r.name;sel.append(o)});if([...sel.options].some(o=>o.value===current))sel.value=current}
let opts;try{opts=await api('/api/catalog/options')}catch(err){msg('error',uiErrorMessage(err,'Não foi possível carregar as opções do catálogo.'));return}fill(categoryId,opts.categories);fill(unitCode,opts.units,'id');
