async function loadSKUs(){if(!currentItem)return;renderSKUs(await api('/api/catalog/items/'+currentItem.id+'/skus'))}
async function selectItem(r){currentItem=r;itemId.value=r.id;itemName.value=r.name;categoryId.value=String(r.category_id||'');unitCode.value=r.unit;minimumStock.value=displayDecimal(r.minimum_stock);itemNotes.value=r.notes||'';itemActive.checked=!!r.active;document.getElementById('itemEditorTitle').textContent=r.name;setCrudMode(itemForm,true,'Criar item pai','Atualizar item pai');editor.hidden=false;empty.hidden=true;skuManager.hidden=false;resetSKUForm();refreshParentOptions(parents);await loadSKUs();renderParents(await api('/api/catalog/items?q='+encodeURIComponent(normalizeBarcode(search.value))))}
