itemForm.addEventListener('submit',async e=>{e.preventDefault();let submit=e.submitter||itemForm.querySelector('button[type="submit"]');if(submit?.dataset.busy==='1')return;await runLocked(submit,async()=>{msg('loading','Salvando item pai…');let body={name:itemName.value,category_id:+categoryId.value,unit_code:unitCode.value,minimum_stock:requestDecimal(minimumStock.value),notes:itemNotes.value,active:itemActive.checked};try{let id=itemId.value,wasEditing=!!id;if(id)await api('/api/catalog/items/'+id,{method:'PATCH',body:JSON.stringify(body)});else{id=(await api('/api/catalog/items',{method:'POST',body:JSON.stringify(body)})).id}let rows=await loadParents('');refreshParentOptions(rows);parents=rows;newItem(false);msg('success',wasEditing?'Item pai atualizado. Formulário pronto para um novo cadastro.':'Item pai criado. Formulário pronto para um novo cadastro.')}catch(err){msg('error',uiErrorMessage(err,'Não foi possível salvar o item pai. Revise os dados e tente novamente.'))}})});
document.getElementById('newCatalogSku').onclick=()=>{resetSKUForm();skuForm.hidden=false;skuParentId.value=String(currentItem.id);document.getElementById('skuEditorTitle').textContent='Novo produto/SKU';setCrudMode(skuForm,false,'Criar SKU','Atualizar SKU');skuName.focus()};
