function zxingFormats(){let z=window.ZXingBrowser||window.ZXing;if(!z||!z.BarcodeFormat)return undefined;return [z.BarcodeFormat.EAN_13,z.BarcodeFormat.EAN_8,z.BarcodeFormat.UPC_A,z.BarcodeFormat.UPC_E,z.BarcodeFormat.CODE_128].filter(Boolean)}
