function stopScanner(hide=true){let scan=activeScan;activeScan=null;if(scan){scan.done=true;if(scan.raf)try{cancelAnimationFrame(scan.raf)}catch(e){}if(scan.reader&&scan.reader.reset)try{scan.reader.reset()}catch(e){}if(scan.reader&&scan.reader.stopContinuousDecode)try{scan.reader.stopContinuousDecode()}catch(e){}if(scan.stream)try{scan.stream.getTracks().forEach(t=>t.stop())}catch(e){}}let area=document.getElementById('scanner'),video=document.getElementById('scanner-video')||document.getElementById('scannerVideo');if(video){try{if(video.srcObject)video.srcObject.getTracks().forEach(t=>t.stop())}catch(e){}try{video.pause()}catch(e){}video.srcObject=null}if(area&&hide){area.hidden=true;area.classList.remove('scanner-open')}if(area&&!hide)area.classList.add('scanner-open');document.body.classList.remove('scan-lock')}
